import React, { useState, useContext } from "react";
import { useNavigate } from "react-router-dom";
import api from "../api";
import { AuthContext } from "../contexts/AuthContext";

export default function Login() {
  const navigate = useNavigate();
  const { login } = useContext(AuthContext);

  const [form, setForm] = useState({ email: "", password: "", totp: "", userId: null });
  const [otpRequired, setOtpRequired] = useState(false);
  const [message, setMessage] = useState("");

  const handleChange = (e) => setForm({ ...form, [e.target.name]: e.target.value });

  const handleSubmit = async (e) => {
    e.preventDefault();
    setMessage("");

    try {
      if (otpRequired) {
        // Verify OTP
        const res = await api.post("/auth/login/verify", {
          userId: form.userId,
          totp: form.totp,
        });
        const { token, user } = res.data;
        login(user, token);

        if (user.role === "admin") navigate("/admin-dashboard");
        else if (user.role === "comelec") navigate("/comelec-dashboard");
        else navigate("/student-dashboard");

        return;
      }

      // Normal login
      const res = await api.post("/auth/login", {
        email: form.email,
        password: form.password,
      });

      console.log("🔎 Login response:", res.data); // debug

      if (res.data.otpRequired) {
        setOtpRequired(true);
        setForm({ ...form, userId: res.data.userId });
        setMessage("Please enter the 6-digit OTP from your Authenticator app.");
        return;
      }

      const { token, user } = res.data;
      if (!token || !user) {
        setMessage("Invalid response from server");
        return;
      }

      login(user, token);

      if (user.role === "admin") navigate("/admin-dashboard");
      else if (user.role === "comelec") navigate("/comelec-dashboard");
      else navigate("/student-dashboard");

    } catch (err) {
      setMessage(err.response?.data?.error || "Login failed");
    }
  };

  return (
    <div style={{ display: "flex", justifyContent: "center", padding: "50px", fontFamily: "Arial, sans-serif" }}>
      <div style={{ width: "400px", padding: "30px", border: "1px solid #ddd", borderRadius: "10px", boxShadow: "0 4px 10px rgba(0,0,0,0.1)" }}>
        <h2 style={{ textAlign: "center", marginBottom: "20px", color: "#333" }}>Login</h2>

        <form onSubmit={handleSubmit} style={{ display: "flex", flexDirection: "column", gap: "15px" }}>
          {!otpRequired && (
            <>
              <input type="email" name="email" placeholder="Email" value={form.email} onChange={handleChange} required />
              <input type="password" name="password" placeholder="Password" value={form.password} onChange={handleChange} required />
            </>
          )}

          {otpRequired && (
            <input
              type="text"
              name="totp"
              placeholder="Enter 6-digit OTP"
              value={form.totp}
              onChange={handleChange}
              required
            />
          )}

          <button type="submit">{otpRequired ? "Verify OTP" : "Login"}</button>
        </form>

        {message && <p>{message}</p>}
      </div>
    </div>
  );
}
